  it("runs a helper that passes its callback's call back into itself as a recursive operator", async () => {
    const getSource = (expected: string) => `
      interface Tree {
        first: number;
        last: number;
        children: Tree[];
      }
      const parseText = (text: string) => {
        const skipSpaces = (index: number) => {
          let end = index;
          while (text[end] === " ") end++;
          return end;
        };
        const parseItems = (
          start: number,
          close: string,
          parseItem: (index: number) => Tree | undefined,
        ): Tree | undefined => {
          const node: Tree = { first: start, last: start, children: [] };
          let index = skipSpaces(start);
          while (index < text.length && text[index] !== close) {
            const item = parseItem(index);
            if (item === undefined) return undefined;
            node.children.push(item);
            index = skipSpaces(item.last + 1);
            if (text[index] === ",") index = skipSpaces(index + 1);
          }
          node.last = index;
          return node;
        };
        const parse = (index: number): Tree | undefined =>
          text[index] === "("
            ? parseItems(index + 1, ")", (inner) => parse(inner))
            : text[index] === undefined || text[index] === ")"
              ? undefined
              : { first: index, last: index, children: [] };
        const show = (tree: Tree | undefined): string => {
          if (tree === undefined) return "?";
          if (tree.children.length === 0) return text[tree.first];
          let shown = "[";
          for (const child of tree.children) shown += show(child);
          return \`\${shown}]\`;
        };
        return show(parse(0));
      };
      const result = \`\${parseText("(a, (b c), d)")};\${parseText("(a, (b")}\`;
      if (result !== "${expected}") throw new Error(result);
    `;
    expect(printModule(compile(getSource("[a[bc]d];[a[b]]")).source)).toMatch(/^parseItems\(/m);
    expect((await checkModel(getSource("[a[bc]d];[a[b]]"))).failure).toBeUndefined();
    expect((await checkModel(getSource("[a[bc]d];?"))).failure?.message).toContain(
      "[a[bc]d];[a[b]]",
    );
  });

  it("runs helpers that call each other as recursive operators that change the caller's names", async () => {
    const getSource = (expected: string, deepest: number) => `
      const run = () => {
        const seen = { count: 0 };
        const trail: string[] = [];
        let depth = 0;
        const isEven = (value: number): boolean => {
          depth++;
          trail.push(\`e\${value}\`);
          seen.count++;
          if (value === 0) return true;
          return isOdd(value - 1);
        };
        const isOdd = (value: number): boolean => {
          trail.push(\`o\${value}\`);
          if (value === 0) return false;
          if (value > 50) throw new Error(\`too deep \${value}\`);
          return isEven(value - 1);
        };
        const first = isEven(4);
        const second = isOdd(3);
        let caught = "none";
        try {
          isEven(52);
        } catch (error) {
          caught = (error as Error).message;
        }
        isEven(${deepest});
        return \`\${first},\${second},\${trail.length},\${trail.slice(0, 5).join("|")},\${depth},\${seen.count},\${caught}\`;
      };
      const text = run();
      if (text !== "${expected}") throw new Error(text);
    `;
    const expected = "true,true,12,e4|o3|e2|o1|e0,7,7,too deep 51";
    const printed = printModule(compile(getSource(expected, 0)).source);
    expect(printed).toMatch(/^RECURSIVE isEven\(/m);
    expect(printed).toMatch(/^isOdd\(/m);
    expect((await checkModel(getSource(expected, 0))).failure).toBeUndefined();
    expect(
      (await checkModel(getSource("true,true,12,e4|o3|e2|o1|e0,6,7,too deep 51", 0))).failure
        ?.message,
    ).toContain(expected);
    expect((await checkModel(getSource(expected, 54))).failure?.message).toContain("too deep 53");
  });

