      const leaf = create("leaf", []);
      const pair = create("pair", [leaf, leaf]);
      const flat = (node: Node, isFlat: boolean) =>
        create("flat", [...(isFlat ? node.heirs : [node]), leaf]);
      const one = flat(pair, true);
