  it("keeps a set's identity through an array, a pop, and its own name", async () => {
    const result = await checkModel(`
      const scopes: Set<string>[] = [];
      const declare = (name: string) => scopes[scopes.length - 1]?.add(name);
      const isDeclared = (name: string) => scopes.some((scope) => scope.has(name));
      const step = () => {
        const scope = new Set<string>();
        scopes.push(scope);
        declare("a");
        scopes.push(new Set());
        declare("b");
        const inner = isDeclared("a") && isDeclared("b");
        scopes.pop();
        scopes.pop();
        declare("c");
        return inner && scope.has("a") && !scope.has("b") && scope.size === 1;
      };
      declare("lost");
      const twin = new Set(["a"]);
      scopes.push(twin);
      const copy = new Set(twin);
      scopes[0].add("b");
      if (!step() || scopes.length !== 1 || copy.size !== 1 || twin.size !== 3) {
        throw new Error("scopes");
      }
      const other = new Set(["a", "b"]);
      if (!scopes.includes(twin) || scopes.indexOf(other) !== -1) {
        throw new Error("identity");
      }
    `);
    expect(result.failure).toBeUndefined();
    const getScopes = (check: string) => `
      const scopes: Set<string>[] = [new Set()];
      const first = scopes[0];
      scopes[0].add("a");
      const json = JSON.stringify(scopes);
      if (json !== "[{}]" || ${check}) throw new Error("scopes " + json);
    `;
    expect((await checkModel(getScopes('!first.has("a")'))).failure).toBeUndefined();
    expect((await checkModel(getScopes('first.has("a")'))).failure?.message).toContain("scopes");
    // add gives the set that the array holds, which later adds change.
    const getAdded = (check: string) => `
      const scopes: Set<string>[] = [new Set()];
      const grown = scopes[0].add("a");
      scopes[0].add("b");
      if (${check}) throw new Error("shared");
    `;
    expect((await checkModel(getAdded('!grown.has("b")'))).failure).toBeUndefined();
    expect((await checkModel(getAdded('grown.has("b")'))).failure?.message).toContain("shared");
  });

