      if (getCount() !== 2 || log[1] !== "foo") throw new Error("log");
      const values = Object.values(proxy);
      if (values.length !== 2 || values[1] !== 2 || getCount() !== 4) throw new Error("values");
      const copy: Record<string | symbol, number> = {};
