      const box = { list: [1] };
      const keep = (value: number[]) => value;
      const run = keep;
      const list = run(box.list);
      list.push(2);
      const other: { field: Error } = { field: new Error("e") };
      other.field.message = "m";
      const item = { count: 1 };
      put(item);
